<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>پروژه‌ها | آزمون‌یار</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header><b>✓ آزمون‌یار</b><nav><a href="/dashboard">داشبورد</a><a href="/projects">پروژه‌ها</a></nav></header><main class="app"><span>مدیریت پروژه</span><h1>پروژه‌ها</h1><p>محیط‌های نرم‌افزاری و برنامهٔ تست هرکدام را سازمان‌دهی کنید.</p><?php if(session('message')): ?><div class="alert"><?=esc(session('message'))?></div><?php endif ?><?php if(session('is_admin')): ?><section><h2>ایجاد پروژهٔ جدید</h2><form method="post" class="grid"><?=csrf_field()?><label>کد پروژه<input name="code" required placeholder="PAYROLL"></label><label>نام پروژه<input name="name" required placeholder="نام محصول"></label><label>نشانی سامانه<input name="target_url" type="url" placeholder="https://..."></label><label class="wide">شرح<textarea name="description"></textarea></label><button class="btn">ایجاد پروژه</button></form></section><?php endif ?><section><h2>فهرست پروژه‌ها</h2><?php if(!$projects): ?><p class="empty">هنوز پروژه‌ای ساخته نشده است.</p><?php else: ?><table><tr><th>کد</th><th>نام پروژه</th><th>وضعیت</th></tr><?php foreach($projects as $project): ?><tr><td><?=esc($project['code'])?></td><td><?=esc($project['name'])?></td><td><i>فعال</i></td></tr><?php endforeach ?></table><?php endif ?></section></main></body></html>
